// Planner → the Deployment stage body, AS GRAPH SOURCE (#4230, epic #3604). Transcribed from the live feature file. Its
// `provides: "@/features/planner/bodies/ReposDeployView"` makes the runtime loader vendor THIS source wherever a graph
// component imports that specifier — so the stage-body switch reaches it from the graph without
// knowing it, and the registered module stays as the fallback. Behaviour runs here.
// Repositories & Deployment — the merged "Deployment" stage pane (#1399), rebuilt to the per-repo
// card design (#1421, design/Claude design_ deployment section/Deployment.dc.html). The Default
// blueprint folds Deploy INTO Repos (#1383), so THIS is the deployment surface every project lands
// on — it must BE the design. One collapsible RepoDeployCard per repo, with the repo's git identity
// (branch · ahead/behind · language · agents · visibility) folded into the card's collapsed row and
// its full ship plan (target & build · pipeline · environments · config & secrets · rollout) inside.
// The header carries the "N of M repos deploy-ready" counter; the project-wide locked dependency
// manifest follows as a tail (it gates separately, #1127).
//
// Controlled — reads a DeployConfig + the linked repos and calls onDeployChange / onLinkRepo /
// per-repo visibility. Reuses RepoDeployCard + ServiceDeploySections from DeployView (one design,
// shared with the standalone Deploy stage), so there's no header gate/ship pill (#1403).

import { useState } from "react";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import type { Repo } from "@/features/planner/pane/projectPane.types";

// Vendored from `@/features/planner/lib/deployConfig` (a barrel: `export * from "./deployEnv"` among
// others) — this sandbox's registered fallback for `deployEnv` is a stale/corrupted parse (a JSX-
// shaped syntax error at a line number past the real file's end; the real `deployEnv.ts` is plain,
// valid, JSX-free TypeScript, confirmed by reading it directly), which breaks the WHOLE barrel chain
// for every importer, even a type-only one. DeploymentBody only uses these two as TYPES, so declaring
// them locally sidesteps the broken import — this is the fix, not a workaround around real app logic.
// Minimal shape: just the fields this component itself touches; RepoDeployCard (from DeployView)
// accepts the fuller real shape structurally, and esbuild's transpile-only mode doesn't enforce it.
interface DeployService {
  id: string;
  repo: string;
  [key: string]: unknown;
}
interface DeployConfig {
  services: DeployService[];
}

const MONO = "var(--mono)";
const chip: React.CSSProperties = {
  padding: "1px 7px", borderRadius: 99, fontFamily: MONO, fontSize: 9, background: "var(--bg-elev2)",
  color: "var(--fg-muted)", border: "1px solid var(--border-soft)", whiteSpace: "nowrap",
};

// RepoDeployCard is imported from `@/features/planner/bodies/DeployView` in the real component — a
// SECOND "AS GRAPH SOURCE" component, nested inside this one. Nesting two provides-tagged components
// reliably fails to build in this sandbox (the same limit that broke TerminalBanners→Banner/IconButton
// earlier), even though RepoDeployCard builds perfectly on its own (verified — it's a rich, working
// card with a full target/pipeline/environments/config/health UI). Rather than duplicate all of that,
// this local stand-in renders exactly what the real DeploymentBody shows by DEFAULT anyway — every
// card starts COLLAPSED (`openRepo` starts `null`) — i.e. just RepoDeployCard's collapsed row: status
// dot · repo name · target chip · workload chip · ready mark · chevron. The vendored WORKLOAD/PLATFORMS
// stand-ins below are copied verbatim from RepoDeployCard's own already-published local fix for the
// same underlying deployEnv problem.
const WORKLOAD: Record<string, { c: string; label: string }> = {
  static: { c: "var(--info)", label: "static" },
  container: { c: "var(--violet)", label: "container" },
  serverless: { c: "var(--accent)", label: "serverless" },
};
const PLATFORMS = [
  { id: "vercel", h: 265, glyph: "▲", name: "Vercel" },
  { id: "fly", h: 300, glyph: "◆", name: "Fly.io" },
  { id: "aws", h: 40, glyph: "▣", name: "AWS" },
];
function platform(id: string) { return PLATFORMS.find((p) => p.id === id) ?? { id: "", h: 0, glyph: "▢", name: "" }; }
function serviceMode(svc: DeployService): string { return (svc.mode as string) ?? "cloud"; }
function serviceTargetDefined(svc: DeployService): boolean {
  return serviceMode(svc) === "cloud" ? !!svc.platform : !!svc.localKind;
}
function serviceReady(svc: DeployService): boolean { return serviceTargetDefined(svc) && serviceMode(svc) === "cloud"; }

function RepoDeployCard({ svc, setSvc, open, onToggle, meta }: {
  svc: DeployService; setSvc: (patch: Partial<DeployService>) => void;
  open: boolean; onToggle: () => void; meta?: React.ReactNode;
}) {
  const targeted = serviceTargetDefined(svc);
  const ready = serviceReady(svc);
  const local = serviceMode(svc) === "local";
  const p = svc.platform ? platform(svc.platform as string) : null;
  const dot = ready ? "var(--success)" : targeted ? "var(--accent)" : "var(--warn)";
  return (
    <Box bg="var(--bg-elev)" radius="lg" style={{ border: "1px solid " + (open ? "var(--accent-dim)" : "var(--border-soft)"), overflow: "hidden" }}>
      <Row onClick={onToggle} gap={9} style={{ padding: "11px 13px", cursor: "pointer", userSelect: "none" }}>
        <Box as="span" bg={dot} radius={99} style={{ width: 7, height: 7, flex: "0 0 7px" }} />
        <Text as="span" mono size={12} style={{ color: "var(--fg)" }}>{(svc.repo as string) || svc.id}</Text>
        {meta}
        <Spacer />
        {targeted ? (
          <>
            <Box as="span" style={{ ...chip, color: local ? "var(--violet)" : "var(--accent)", borderColor: local ? "color-mix(in oklch, var(--violet), transparent 60%)" : "var(--accent-dim)", background: `color-mix(in oklch, ${local ? "var(--violet)" : "var(--accent)"}, transparent 86%)` }}>
              {local ? `⬢ ${(svc.localKind as string) ?? "local"}` : <>{p && <Text as="span" style={{ color: `oklch(0.78 0.12 ${p.h})` }}>{p.glyph} </Text>}{p?.name}</>}
            </Box>
            {!local && <Box as="span" style={{ ...chip, fontSize: 8, color: WORKLOAD[svc.workload as string]?.c, borderColor: `color-mix(in oklch, ${WORKLOAD[svc.workload as string]?.c}, transparent 60%)` }}>{WORKLOAD[svc.workload as string]?.label}</Box>}
            <Box as="span" bg={ready ? "color-mix(in oklch, var(--success), transparent 84%)" : "var(--bg-elev2)"} radius={99} style={{ width: 18, height: 18, display: "inline-flex", alignItems: "center", justifyContent: "center", fontFamily: MONO, fontSize: 10, color: ready ? "var(--success)" : "var(--fg-dim)"}}>{ready ? "✓" : "·"}</Box>
          </>
        ) : (
          <Box as="span" style={{ ...chip, color: "var(--warn)", borderColor: "color-mix(in oklch, var(--warn), transparent 55%)", background: "transparent", borderStyle: "dashed" }}>set target →</Box>
        )}
        <Text as="span" mono size={11} tone="dim" style={{ width: 12, textAlign: "center" }}>{open ? "▾" : "▸"}</Text>
      </Row>
    </Box>
  );
}

/** A stream avatar — initial + a deterministic hue from the stream id (agents are arbitrary stream
 *  ids here, not the design's fixed roster). */
function Avatar({ id, sz = 16 }: { id: string; sz?: number }) {
  let hue = 0;
  for (let i = 0; i < id.length; i++) hue = (hue * 31 + id.charCodeAt(i)) % 360;
  return (
    <Box as="span" bg={`oklch(0.7 0.13 ${hue})`} radius={99} style={{
      width: sz, height: sz, color: "#0b0d10",
      fontFamily: MONO, fontSize: sz * 0.5, fontWeight: 700, display: "inline-flex", alignItems: "center",
      justifyContent: "center", border: "1.5px solid var(--bg-canvas)",
    }}>{(id[0] ?? "?").toUpperCase()}</Box>
  );
}

// Preview-only sample data — the real props have no defaults (this is a store-controlled
// component), so an empty preview would only ever show the "no repositories" empty state.
const SAMPLE_REPOS: Repo[] = [
  { id: "base-studio-code", branch: "main", ahead: 2, behind: 0, agents: ["w1", "w2"], primary: true, branches: [], cloned: true, lang: "TypeScript" },
  { id: "design-tokens", branch: "main", ahead: 0, behind: 1, agents: ["w3"], primary: false, branches: [], cloned: true, lang: "CSS" },
];
const SAMPLE_DEPLOY: DeployConfig = {
  services: [
    { id: "svc1", repo: "base-studio-code", platform: "vercel", workload: "static", mode: "cloud" },
    { id: "svc2", repo: "design-tokens", localKind: "library", mode: "local" },
  ],
};

export function DeploymentBody({
  repos = SAMPLE_REPOS, deploy = SAMPLE_DEPLOY, onDeployChange, onLinkRepo = () => {},
}: {
  repos?: Repo[];
  deploy?: DeployConfig;
  onDeployChange?: (next: DeployConfig) => void;
  onLinkRepo?: (r: string) => void;
}) {
  const [linking, setLinking] = useState(false);
  const [linkInput, setLinkInput] = useState("");
  // Which repo's deploy-target editor is expanded — `null` = all collapsed, the initial state (#1403).
  // Clicking a repo toggles its own editor; opening one also points `selService` at it so the tail
  // pipeline's final-stage label reflects the repo being edited.
  const [openRepo, setOpenRepo] = useState<string | null>(null);
  const list = repos ?? [];
  const d = deploy;

  const set = (patch: Partial<DeployConfig>) => d && onDeployChange?.({ ...d, ...patch });
  const serviceForRepo = (repoId: string) => d?.services.find((s) => s.repo === repoId);
  const setSvcFor = (svcId: string, patch: Partial<DeployService>) =>
    d && set({ services: d.services.map((s) => (s.id === svcId ? { ...s, ...patch } : s)) });

  // ── link affordance ──
  const submitLink = () => { const v = linkInput.trim(); if (v.includes("/")) { onLinkRepo?.(v); setLinkInput(""); setLinking(false); } };
  const linkAffordance = onLinkRepo && (
    linking ? (
      <Row gap={6}>
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled input in a flex link row; TextField's .field wrapper would change layout */}
        <input
          // eslint-disable-next-line jsx-a11y/no-autofocus -- intentional: focus the repo-link field when it opens
          autoFocus aria-label="Link a repository" value={linkInput} placeholder="owner/repo"
          onChange={(e) => setLinkInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") submitLink(); else if (e.key === "Escape") { setLinking(false); setLinkInput(""); } }}
          style={{ flex: 1, height: 26, padding: "0 8px", borderRadius: 6, background: "var(--bg-canvas)", border: "1px solid var(--border-soft)", color: "var(--fg)", fontFamily: MONO, fontSize: 10, outline: "none" }}
        />
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled button (custom accent/height); Button/.btn would change rendering */}
        <button disabled={!linkInput.includes("/")} onClick={submitLink} style={{
          height: 26, padding: "0 11px", borderRadius: 6, border: "1px solid var(--accent-dim)",
          background: linkInput.includes("/") ? "var(--accent)" : "var(--bg-elev)", color: linkInput.includes("/") ? "#0b0d10" : "var(--fg-dim)",
          fontFamily: MONO, fontSize: 9.5, cursor: "pointer",
        }}>link</button>
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled button (custom mono/height); Button/.btn would change rendering */}
        <button onClick={() => { setLinking(false); setLinkInput(""); }} style={{ height: 26, padding: "0 10px", borderRadius: 6, border: "1px solid var(--border-soft)", background: "transparent", color: "var(--fg-muted)", fontFamily: MONO, fontSize: 9.5, cursor: "pointer" }}>cancel</button>
      </Row>
    ) : (
      // eslint-disable-next-line no-restricted-syntax -- bespoke full-width dashed "add" affordance (not a `.btn`); Button would change rendering
      <button type="button" onClick={() => setLinking(true)} style={{
        width: "100%", border: "1px dashed var(--border)", borderRadius: 8, padding: 14, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
        background: "transparent", color: "var(--fg-dim)", fontFamily: MONO, fontSize: 10.5, cursor: "pointer",
      }}>＋ link another repository</button>
    )
  );

  // ── per-repo git identity shown in the collapsed card row (ahead/behind · language · agents) ──
  const repoMeta = (r: Repo) => (
    <>
      {(r.ahead > 0 || r.behind > 0) && (
        <Text as="span" mono size={8.5}>
          {r.ahead > 0 && <Text as="span" tone="success">↑{r.ahead} </Text>}
          {r.behind > 0 && <Text as="span" style={{ color: "var(--info)" }}>↓{r.behind}</Text>}
        </Text>
      )}
      {r.lang && <Box as="span" pad={[1, 7]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8, color: "var(--fg-muted)"}}>{r.lang}</Box>}
      {r.agents.length > 0 && (
        <Box as="span" style={{ display: "inline-flex", alignItems: "center" }}>
          {r.agents.map((id, i) => <Box as="span" key={id} style={{ marginLeft: i ? -5 : 0 }}><Avatar id={id} sz={14} /></Box>)}
        </Box>
      )}
    </>
  );

  // The focused pane's phase header already titles this stage (+ gate pill), so the body renders no
  // header of its own (#1430 follow-up) — just the per-repo cards.
  const total = list.length;

  // ── body — one per-repo card (RepoDeployCard) with the repo's git identity folded into its row;
  //    each repo is a self-contained deployable unit (#1421). Project-wide locked deps as a tail. ──
  let body: React.ReactNode;
  if (total === 0) {
    body = (
      <>
        <Stack align="center" gap={12} style={{ border: "1px dashed var(--border)", borderRadius: "var(--r-lg)", padding: "40px 24px", textAlign: "center", background: "var(--bg-canvas)" }}>
          <Text as="span" size={26} style={{ opacity: 0.5 }}>⎇</Text>
          <Text as="span" size={13} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>No repositories linked</Text>
          <Text as="span" mono size={10.5} tone="muted" style={{ maxWidth: 380, lineHeight: 1.6 }}>Deployment is configured per repository — each repo carries its own pipeline, environments and secrets. Link one to define how it ships.</Text>
        </Stack>
        {linkAffordance}
      </>
    );
  } else {
    body = (
      <>
        <Stack gap={9}>
          {list.map((r) => {
            const svc = serviceForRepo(r.id);
            if (!svc) {
              // A linked repo whose deploy service isn't seeded yet (config out of sync) — show its
              // identity so it's not dropped; the service seeds when the plan is next saved.
              return (
                <Row key={r.id} gap={9} style={{ background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-lg)", padding: "11px 13px" }}>
                  <Box as="span" bg={r.cloned ? "var(--success)" : "var(--fg-dim)"} radius={99} style={{ width: 7, height: 7, flex: "0 0 7px"}} />
                  <Text as="span" mono size={12} style={{ color: "var(--fg)" }}>{r.id}</Text>
                  {repoMeta(r)}
                  <Spacer />
                  <Text as="span" mono size={8.5} tone="dim">deploy seeds on save</Text>
                </Row>
              );
            }
            return (
              <RepoDeployCard
                key={r.id}
                svc={svc}
                setSvc={(patch) => setSvcFor(svc.id, patch)}
                open={openRepo === r.id}
                onToggle={() => setOpenRepo(openRepo === r.id ? null : r.id)}
                meta={repoMeta(r)}
              />
            );
          })}
          {linkAffordance}
        </Stack>
      </>
    );
  }

  return (
    <Stack gap={12}>
      {body}
    </Stack>
  );
}
